<?php

declare(strict_types=1);

namespace Connectors\Secrets;

use Illuminate\Support\Env;

/**
 * Local and CI only. Reads AMPLIRAIL_SECRET_<REF> environment variables (generated by php artisan amplirail:secrets:local).
 * Refused in production (SECURITY.md: never .env in production).
 */
final class EnvSecretsResolver implements SecretsResolver
{
    public function __construct(private readonly bool $isProduction)
    {
        if ($isProduction) {
            throw new \LogicException('The env secrets driver is not allowed in production. Use SECRETS_DRIVER=aws.');
        }
    }

    public static function variableFor(string $ref): string
    {
        return 'AMPLIRAIL_SECRET_'.strtoupper((string) preg_replace('/[^A-Za-z0-9]+/', '_', $ref));
    }

    public function get(string $ref): string
    {
        $value = Env::get(self::variableFor($ref));
        if (! is_string($value) || $value === '') {
            throw SecretUnavailable::for($ref, 'set '.self::variableFor($ref).' for local use');
        }

        return $value;
    }

    public function exists(string $ref): bool
    {
        $value = Env::get(self::variableFor($ref));

        return is_string($value) && $value !== '';
    }
}
